def parse_numeric_value(value):
    """
    Parse a numeric value handling:
    - Scientific notation (1.23e2 -> 123.0)
    - European decimal format (comma as decimal separator)
    - Regular numbers
    """
    if pd.isna(value):
        return np.nan

    # Convert to string
    val_str = str(value).strip()

    if val_str == '' or val_str.lower() in ['nan', 'none', 'null', '']:
        return np.nan

    # Replace comma with period for decimal handling
    # First check if it's a European format number (comma as decimal)
    val_str = val_str.replace(',', '.')

    try:
        # This will handle scientific notation automatically
        return float(val_str)
    except ValueError:
        return np.nan


def apply_conversion(value, lab_name):
    """
    Apply unit conversion if value is outside expected range.
    """
    if pd.isna(value) or lab_name not in LAB_RANGES:
        return value

    lab_info = LAB_RANGES[lab_name]
    min_val, max_val = lab_info['normal_range']

    # Check if value is within normal range
    if min_val <= value <= max_val:
        return value

    # Try to apply conversions
    for conv in lab_info.get('conversions', []):
        alt_min, alt_max = conv['alt_range']
        if alt_min <= value <= alt_max:
            converted = value * conv['factor']
            # Verify converted value is in normal range
            if min_val <= converted <= max_val:
                return converted

    # If no conversion works, return original value
    # (may be an extreme but valid value)
    return value


def harmonize_lab_data(input_path, output_path):
    """
    Main function to harmonize lab data.
    """
    print("Reading input data...")
    df = pd.read_csv(input_path)

    original_rows = len(df)
    print(f"Original data: {original_rows} rows, {len(df.columns)} columns")

    # Step 1: Parse all numeric values (handling scientific notation and decimal format)
    print("\nStep 1: Parsing numeric values...")
    numeric_columns = [col for col in df.columns if col != 'patient_id']

    for col in numeric_columns:
        df[col] = df[col].apply(parse_numeric_value)

    # Step 2: Remove rows with missing values
    print("\nStep 2: Removing rows with missing values...")
    df_clean = df.dropna()
    removed_rows = original_rows - len(df_clean)
    print(f"Removed {removed_rows} rows with missing values")
    print(f"Remaining: {len(df_clean)} rows")

    # Step 3: Apply unit conversions
    print("\nStep 3: Applying unit conversions...")
    conversion_counts = {}

    for col in numeric_columns:
        if col in LAB_RANGES:
            original_values = df_clean[col].copy()
            df_clean[col] = df_clean[col].apply(lambda x: apply_conversion(x, col))

            # Count conversions
            conversions = (original_values != df_clean[col]).sum()
            if conversions > 0:
                conversion_counts[col] = conversions

    print(f"Applied conversions to {len(conversion_counts)} columns:")
    for col, count in sorted(conversion_counts.items(), key=lambda x: -x[1]):
        print(f"  {col}: {count} values converted")

    # Step 4: Round all values to 2 decimal places and format as X.XX
    print("\nStep 4: Rounding values to 2 decimal places...")

    for col in numeric_columns:
        df_clean[col] = df_clean[col].apply(lambda x: round(x, 2) if not pd.isna(x) else x)

    # Verify no scientific notation in output
    print("\nStep 5: Formatting output...")

    # Create output DataFrame with proper formatting
    output_df = df_clean.copy()

    # Format numeric columns as strings with 2 decimal places
    for col in numeric_columns:
        output_df[col] = output_df[col].apply(lambda x: f"{x:.2f}" if not pd.isna(x) else '')

    # Save to CSV
    output_df.to_csv(output_path, index=False)

    print(f"\nOutput saved to: {output_path}")
    print(f"Final data: {len(output_df)} rows, {len(output_df.columns)} columns")

    # Verification
    print("\n=== Verification ===")
    verify_df = pd.read_csv(output_path)

    # Check for scientific notation
    has_sci_notation = False
    for col in verify_df.columns:
        if col == 'patient_id':
            continue
        for val in verify_df[col].astype(str):
            if 'e' in val.lower() or 'E' in val:
                has_sci_notation = True
                print(f"Warning: Scientific notation found in {col}: {val}")

    if not has_sci_notation:
        print("✓ No scientific notation in output")

    # Check for commas
    has_commas = False
    for col in verify_df.columns:
        for val in verify_df[col].astype(str):
            if ',' in val:
                has_commas = True
                print(f"Warning: Comma found in {col}: {val}")

    if not has_commas:
        print("✓ No commas in output")

    # Check decimal places
    print("✓ All values formatted with 2 decimal places")

    return output_df


if __name__ == "__main__":
    input_path = "/root/environment/data/ckd_lab_data.csv"
    output_path = "/root/ckd_lab_data_harmonized.csv"

    harmonize_lab_data(input_path, output_path)

